begin;
set local app.allow_legacy_alpha_testers='on';
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(12);
select has_table('public','profiles','profiles exist');
select has_table('public','residents','residents exist');
select has_table('public','player_resources','resources exist');
select has_table('public','economy_transactions','immutable ledger exists');
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)values('00000000-0000-0000-0000-000000000000','10000000-0000-4000-8000-000000000001','authenticated','authenticated','m1@example.test',crypt('password',gen_salt('bf')),now(),'{}','{"username":"MilestoneOne"}',now(),now(),'','','','');
select is((select coins from public.player_economy where player_id='10000000-0000-4000-8000-000000000001'),500::bigint,'starter Coins provisioned');
select is((select energy from public.residents where player_id='10000000-0000-4000-8000-000000000001'),100,'starter Energy provisioned');
select is((select count(*)from public.player_resources where player_id='10000000-0000-4000-8000-000000000001'),8::bigint,'all resources provisioned');
select is((select count(*)from public.player_skills where player_id='10000000-0000-4000-8000-000000000001'),7::bigint,'all skills provisioned');
set local role authenticated;select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select is(public.get_player_game_state()->>'playerId',auth.uid()::text,'own state loads');
select is((select count(*)from public.profiles where id<>auth.uid()),0::bigint,'RLS hides other profiles');
select throws_like($$update public.player_economy set coins=999 where player_id=auth.uid()$$,'%permission denied%','direct economy mutation denied');
reset role;insert into public.economy_transactions(player_id,transaction_type,resource,amount,balance_before,balance_after,reference_id)values('10000000-0000-4000-8000-000000000001','TEST','coins',1,500,501,'10000000-0000-4000-8000-000000000099');
select throws_like($$update public.economy_transactions set amount=2 where reference_id='10000000-0000-4000-8000-000000000099'$$,'%immutable%','ledger rejects updates');
select * from finish();rollback;
